begin;
create extension if not exists pgtap with schema extensions;
select plan(36);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values('99000000-0000-4000-8000-000000000011','ticket09-dm@verification.test','{}','{}'),('99000000-0000-4000-8000-000000000012','ticket09-player@verification.test','{}','{}');
insert into public.party_members(party_id,user_id,role) values('00000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000011','dungeon-master'),('00000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000012','player');
insert into storage.objects(bucket_id,name,metadata) select 'party-handouts','00000000-0000-4000-8000-000000000001/'||id,'{"size":68,"mimetype":"image/png"}'::jsonb from unnest(array['99000000-0000-4000-8000-000000000050','99000000-0000-4000-8000-000000000052']) as id;
create function pg_temp.stroke(p_request uuid,p_revision integer,p_cells jsonb) returns jsonb language sql as $$
select public.commit_map_reveal_mask(p_request,p_revision,'99000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000009','{"columns":8,"rows":6,"feetPerSquare":5,"background":null}',p_cells);
$$;
set local role authenticated;
set local "request.jwt.claim.sub"='99000000-0000-4000-8000-000000000011';
select lives_ok($$select public.attach_map_artwork_version('99000000-0000-4000-8000-000000000001',null,0,'99000000-0000-4000-8000-000000000003','Ticket09 A','{"columns":8,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}',null,null,'','A')$$,'DM creates private family A');
select lives_ok($$select public.attach_map_artwork_version('99000000-0000-4000-8000-000000000002',null,0,'99000000-0000-4000-8000-000000000004','Ticket09 B','{"columns":8,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}',null,null,'','B')$$,'DM creates private family B');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000003',0,'99000000-0000-4000-8000-000000000009',false)->'presentation'->'mask'->'uncovered','[]'::jsonb,'new family starts hidden');
select is(pg_temp.stroke('99000000-0000-4000-8000-000000000010',1,'[9,2]')->'presentation'->'mask'->'uncovered','[2,9]'::jsonb,'stroke commits sorted validated cells');
select is((pg_temp.stroke('99000000-0000-4000-8000-000000000010',1,'[2,9]')->'presentation'->>'revision')::integer,2,'semantic retry returns accepted receipt');
select throws_ok($$select pg_temp.stroke('99000000-0000-4000-8000-000000000010',1,'[3]')$$,'P0001','Presentation request already used','same request different mask rejected');
select is(pg_temp.stroke('99000000-0000-4000-8000-000000000020',1,'[3]')->>'reason','conflict','second controller stale revision conflicts');
select is((public.read_map_workspace()->'presentation'->>'revision')::integer,2,'stale conflict does not advance accepted revision');
select is((select count(*) from public.party_map_reveal_masks),1::bigint,'accepted progress retained once');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000004',2,'99000000-0000-4000-8000-000000000021',true)->'presentation'->'mask'->'uncovered','[]'::jsonb,'family B starts hidden');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000003',3,'99000000-0000-4000-8000-000000000022',true)->'presentation'->'mask'->'uncovered','[2,9]'::jsonb,'return to compatible family A restores accepted progress');
select lives_ok($$select public.attach_map_artwork_version('99000000-0000-4000-8000-000000000001',null,1,'99000000-0000-4000-8000-000000000023','Ticket09 A changed','{"columns":10,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}',null,null,'','changed')$$,'new incompatible geometry is saved privately');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000023',4,'99000000-0000-4000-8000-000000000024',false)->>'reason','incompatible','incompatible geometry requires explicit new map setup');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000023',4,'99000000-0000-4000-8000-000000000025',true)->'presentation'->'mask'->'uncovered','[]'::jsonb,'explicit incompatible setup starts hidden');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000003',5,'99000000-0000-4000-8000-000000000026',true)->'presentation'->'mask'->'uncovered','[2,9]'::jsonb,'old compatible geometry remains durably retained');
select throws_ok($$select pg_temp.stroke('99000000-0000-4000-8000-000000000030',6,'[48]')$$,'P0001','Invalid Reveal Mask','out of bounds mask rejected server-side');
select throws_ok($$select pg_temp.stroke('99000000-0000-4000-8000-000000000030',6,'[1,1]')$$,'P0001','Invalid Reveal Mask','duplicate cell mask rejected server-side');
select throws_ok($$select pg_temp.stroke('99000000-0000-4000-8000-000000000030',6,'[1.5]')$$,'P0001','Invalid Reveal Mask','fractional cell mask rejected server-side');
select throws_ok($$select pg_temp.stroke('99000000-0000-4000-8000-000000000030',6,'null')$$,'P0001','Invalid Reveal Mask','missing cells rejected server-side');
select throws_ok($$update public.party_map_presentations set mask=mask||'{"uncovered":[47]}'$$,'42501','permission denied for table party_map_presentations','DM cannot bypass semantic atomic command');
select throws_ok($$delete from public.party_map_reveal_masks$$,'42501','permission denied for table party_map_reveal_masks','DM cannot erase progress by direct mutation');
select lives_ok($$select public.attach_map_artwork_version('99000000-0000-4000-8000-000000000008',null,0,'99000000-0000-4000-8000-000000000050','Ticket09 C artwork','{"columns":8,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}',jsonb_build_object('x',1,'y',0,'width',6,'height',6,'pixelWidth',8,'pixelHeight',8,'mime','image/png','size',68,'digest',repeat('a',64),'object_id','99000000-0000-4000-8000-000000000050'),null,'','C')$$,'first registered artwork saved');
select lives_ok($$select public.choose_map_presentation('99000000-0000-4000-8000-000000000050',6,'99000000-0000-4000-8000-000000000051',true)$$,'registered family starts hidden');
select is(public.commit_map_reveal_mask('99000000-0000-4000-8000-000000000053',7,'99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000051','{"columns":8,"rows":6,"feetPerSquare":5,"background":{"registration":"upload:99000000-0000-4000-8000-000000000050","x":1,"y":0,"width":6,"height":6,"pixelWidth":8,"pixelHeight":8}}','[1]')->'presentation'->'mask'->'uncovered','[1]'::jsonb,'registered artwork stroke accepted');
select lives_ok($$select public.save_party_grid_map('99000000-0000-4000-8000-000000000008',1,'99000000-0000-4000-8000-000000000052','Ticket09 C replacement','{"columns":8,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}','replace',jsonb_build_object('x',1,'y',0,'width',6,'height',6,'pixelWidth',8,'pixelHeight',8,'mime','image/png','size',68,'digest',repeat('a',64),'object_id','99000000-0000-4000-8000-000000000052'),'C2')$$,'same digest/dimensions different registration saved');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000052',8,'99000000-0000-4000-8000-000000000054',false)->>'reason','incompatible','registration-only change requires explicit setup');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000052',8,'99000000-0000-4000-8000-000000000054',true)->'presentation'->'mask'->'uncovered','[]'::jsonb,'explicit new registration does not reuse cells');
select is(public.choose_map_presentation('99000000-0000-4000-8000-000000000050',9,'99000000-0000-4000-8000-000000000055',true)->'presentation'->'mask'->'uncovered','[1]'::jsonb,'returning to old registration restores only its cells');
select is(public.commit_map_reveal_mask('99000000-0000-4000-8000-000000000056',10,'99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000051','{"columns":8,"rows":6,"feetPerSquare":5,"background":{"registration":"upload:99000000-0000-4000-8000-000000000050","x":0,"y":0,"width":6,"height":6,"pixelWidth":8,"pixelHeight":8}}','[2]')->>'reason','incompatible','forged canonical placement cannot reinterpret mask');
select is(public.commit_map_reveal_mask('99000000-0000-4000-8000-000000000056',10,'99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000051','{"columns":8,"rows":6,"feetPerSquare":5,"background":{"registration":"other","x":1,"y":0,"width":6,"height":6,"pixelWidth":8,"pixelHeight":8}}','[2]')->>'reason','incompatible','forged registration cannot reinterpret mask');
select throws_ok($$select public.commit_map_reveal_mask('99000000-0000-4000-8000-000000000055',10,'99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000051','{"columns":8,"rows":6,"feetPerSquare":5,"background":{"registration":"upload:99000000-0000-4000-8000-000000000050","x":1,"y":0,"width":6,"height":6,"pixelWidth":8,"pixelHeight":8}}','[2]')$$,'P0001','Presentation request already used','choose request cannot be reused as mask command');
set local "request.jwt.claim.sub"='99000000-0000-4000-8000-000000000012';
select is((select count(*) from public.party_map_reveal_masks),0::bigint,'player cannot read retained masks');
select is((select count(*) from public.party_map_presentation_requests),0::bigint,'player cannot read mask/stroke receipts');
select throws_ok($$select pg_temp.stroke('99000000-0000-4000-8000-000000000040',6,'[3]')$$,'42501','Dungeon Master access is required','player cannot commit mask even with known identities');
set local role anon;
select throws_ok($$select * from public.party_map_reveal_masks$$,'42501','permission denied for table party_map_reveal_masks','anonymous mask read denied');
select throws_ok($$select public.commit_map_reveal_mask('99000000-0000-4000-8000-000000000040',6,'99000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000009','{"columns":8,"rows":6,"feetPerSquare":5,"background":null}','[3]')$$,'42501','permission denied for function commit_map_reveal_mask','anonymous mask commit denied');
select * from finish();
rollback;
